using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Threading.Tasks;
using RoomManager;
class Integration {
 static int checks;static string endpoint,password,output;
 static void Assert(bool condition,string name){if(!condition)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static async Task Ready(ApiClient c){for(int i=0;i<100&&!c.Connected;i++)await Task.Delay(100);Assert(c.Connected,"完整 WS 快照 "+c.LastError);}
 static async Task<object> Command(ApiClient c,string op,object args,bool success=true,object tokens=null){var r=await c.Send(c.Envelope(op,args,tokens));Assert(J.S(r,"status")== (success?"committed":"rejected"),op+" "+J.Text(r));await Task.Delay(300);return J.Get(r,"result");}
 static async Task Reject(Func<Task> task,string name){try{await task();throw new Exception("预期拒绝："+name);}catch(ApiException){Assert(true,name);}}
 static void Throws(Action action,string name){try{action();throw new Exception("未拒绝 "+name);}catch(ApiException){Assert(true,name);}}
 static object Tokens(ApiClient c,string id){return J.Obj(id,J.Get(J.Get(J.Get(c.View,"entities"),id),"viewToken"));}
 static void Units(){
  foreach(string url in new[]{"https://localhost:9","http://evil.test","http://user@localhost","http://localhost/a","http://localhost/?x=1"})Throws(()=>ApiClient.ValidateOrigin(url),"拒绝非回环根地址");
  var a=new SnapshotAssembler();a.Accept(J.Obj("type","snapshot.begin","id","a","parts",2));a.Accept(J.Obj("type","snapshot.part","id","a","index",1,"data","1}"));a.Accept(J.Obj("type","snapshot.part","id","a","index",0,"data","{\"x\":"));Assert(J.I(a.Accept(J.Obj("type","snapshot.end","id","a")),"x")==1,"乱序分片完整组装");
  a.Accept(J.Obj("type","snapshot.begin","id","a","parts",2));Throws(()=>a.Accept(J.Obj("type","snapshot.end","id","a")),"缺片不发布");a.Reset();a.Accept(J.Obj("type","snapshot.begin","id","a","parts",1));a.Accept(J.Obj("type","snapshot.part","id","a","index",0,"data","{}"));Throws(()=>a.Accept(J.Obj("type","snapshot.part","id","a","index",0,"data","{}")),"重复分片拒绝");
  var tiny=new SnapshotAssembler(2);tiny.Accept(J.Obj("type","snapshot.begin","id","a","parts",1));Throws(()=>tiny.Accept(J.Obj("type","snapshot.part","id","a","index",0,"data","123")),"超限分片拒绝");
  var o=new Observer();o.Sample("view",J.Obj("a/b",J.Obj("value",1,"viewToken","a")));Assert(o.Records.Count==0,"首样本仅作基线");o.Sample("view",J.Obj("a/b",J.Obj("value",2,"viewToken","b","nullable",null)));Assert(o.Records.Count==2&&J.S(o.Records[1],"path").StartsWith("/a~1b/"),"路径转义和令牌过滤");Assert(o.Records.Any(x=>!J.B(x,"beforePresent")&&J.Get(x,"after")==null),"缺失和 null 分离");o.Sample("view",J.Obj());Assert(J.S(o.Records.Last(),"kind")=="不再可见","消失不推断删除");o.Reset();o.Sample("view",J.Obj("x",10));o.Sample("view",J.Obj("x",10));Assert(o.Records.Count==0,"合并中间态不伪造变化");
  for(int i=0;i<2100;i++)o.Sample("view",J.Obj("x",i));Assert(o.Records.Count==2000,"观察环上限 2000");
  string big=J.Text(J.Obj("payload",new string('x',2000000)));var watch=Stopwatch.StartNew();a.Reset();int count=(big.Length+23999)/24000;a.Accept(J.Obj("type","snapshot.begin","id","large","parts",count));for(int i=0;i<count;i++)a.Accept(J.Obj("type","snapshot.part","id","large","index",i,"data",big.Substring(i*24000,Math.Min(24000,big.Length-i*24000))));var full=a.Accept(J.Obj("type","snapshot.end","id","large"));o.Reset();o.Sample("view",full);o.Sample("view",full);watch.Stop();Assert(J.S(full,"payload").Length==2000000,"接近 2 MiB 快照");File.WriteAllText(Path.Combine(output,"performance.json"),J.Pretty(J.Obj("snapshotBytes",big.Length,"assembleAndObserveMs",watch.ElapsedMilliseconds,"managedBytesAfterGc",GC.GetTotalMemory(true),"peakWorkingSetBytes",Process.GetCurrentProcess().PeakWorkingSet64,"observationLimit",2000,"watchLimit",100)));
  var local=new Settings(Path.Combine(output,"unit-settings"));local.Remember("http://localhost:1/",J.Obj("accountId","kp","roomId","demo","runId","run"),J.Obj("payload",J.Obj("commandId","id","op","entity.patch","args",J.Obj("name","PRIVATE"))));Assert(!File.ReadAllText(Path.Combine(output,"unit-settings/settings.json")).Contains("PRIVATE"),"本地命令元数据不保存参数");
 }
 static async Task Run(){Units();using(var wrong=new ApiClient(endpoint))await Reject(()=>wrong.Login("kp","wrong-password"),"错误密码拒绝");using(var player=new ApiClient(endpoint))await Reject(()=>player.Login("player1",password),"玩家不可进入管理工具");
  using(var one=new ApiClient(endpoint))using(var two=new ApiClient(endpoint)){
   await one.Login("kp",password);await two.Login("kp",password);await Ready(one);await Ready(two);var admin=await one.Admin();Assert(J.D(J.Get(admin,"configurations")).Count>0,"管理读取");
   await Command(one,"configuration.put",J.Obj("configurationId","test.item","revision","1","typeRef","item","defaults",J.Obj("quantity",1,"durability",80),"behaviors",J.Obj()));await Command(one,"configuration.put",J.Obj("configurationId","delete.me","revision","1","typeRef","status","defaults",J.Obj(),"behaviors",J.Obj()));await Command(one,"configuration.remove",J.Obj("id","delete.me"));await Command(one,"configuration.put",J.Obj("configurationId","test.item","revision","1","typeRef","item","defaults",J.Obj("quantity",2),"behaviors",J.Obj()),false);string id=Convert.ToString(await Command(one,"entity.create",J.Obj("configurationId","test.item","name","中文测试物品")));
   await Command(one,"configuration.put",J.Obj("configurationId","test.item","revision","2","typeRef","item","defaults",J.Obj("quantity",1,"durability",90),"behaviors",J.Obj()));Assert(J.I(J.Get(J.Get(J.Get(one.View,"entities"),id),"numbers"),"durability")==80,"修改默认值不迁移实例");await Command(one,"configuration.remove",J.Obj("id","test.item"),false);
   await Task.Delay(500);object stale=two.Envelope("entity.patch",J.Obj("id",id,"name","迟到编辑"),Tokens(two,id));await Command(one,"entity.patch",J.Obj("id",id,"name","先提交"),true,Tokens(one,id));await Reject(async()=>{await two.Send(stale);},"两会话旧 token 冲突");
   await Command(one,"entity.update",J.Obj("id",id,"numbers",J.Obj("durability",77),"tags",new[]{"melee"},"owner","player1","visibility","owner","rules",J.Obj()),true,Tokens(one,id));
   string relation=Convert.ToString(await Command(one,"relation.set",J.Obj("sourceId","actor-player1","targetId",id,"relationType","references")));await Command(one,"entity.archive",J.Obj("id",id),false,Tokens(one,id));await Command(one,"relation.remove",J.Obj("id",relation));await Command(one,"relation.set",J.Obj("sourceId","missing","targetId",id,"relationType","references"),false);
   await Command(one,"progress.set",J.Obj("ownerKind","entity","ownerId",id,"eventKey","unlocked","value",true));await Command(one,"member.update",J.Obj("accountId","player2","active",true));await Command(one,"member.update",J.Obj("accountId","kp","active",false),false);
   var saved=one.Envelope("entity.patch",J.Obj("id",id,"name","只执行一次"),Tokens(one,id));var first=await one.Send(saved);await Task.Delay(350);var rev=J.I(J.Get(J.Get(one.View,"entities"),id),"revision");var receipt=await one.Receipt(J.S(J.Get(saved,"payload"),"commandId"));var duplicate=await one.Send(saved);await Task.Delay(350);Assert(J.Canon(first)==J.Canon(receipt)&&J.Canon(first)==J.Canon(duplicate)&&J.I(J.Get(J.Get(one.View,"entities"),id),"revision")==rev,"丢弃响应后查询与原封套重发只执行一次");
   var upload=await one.Request("assets","POST",null,new byte[]{1,2,3,4},"test.bin","public");string asset=J.S(upload,"assetId");Assert((await one.Download(asset)).SequenceEqual(new byte[]{1,2,3,4}),"素材上传下载");await Command(one,"asset.attach",J.Obj("entityId",id,"assetId",asset),true,Tokens(one,id));await Command(one,"asset.remove",J.Obj("assetId",asset),false);var unused=await one.Request("assets","POST",null,new byte[]{5},"unused.bin","kp");await Command(one,"asset.remove",J.Obj("assetId",J.S(unused,"assetId")));
   string old=J.S(J.Get(one.View,"catalog"),"rulesetRevision");await Command(one,"rule.stage",J.Obj("sources",J.Obj("bad.lua","INVALID LUA")),false);Assert(J.S(J.Get(one.View,"catalog"),"rulesetRevision")==old,"失败暂存不改变激活版本");
   string staged=Convert.ToString(await Command(one,"rule.stage",J.Obj("sources",J.Obj("test.lua","return rule('test.noop', {}, function(r) return 42 end)","retry.lua","return flow('test.retry', {}, { step('fail', function(r) error('test') end) })","wait.lua","return flow('test.wait', {}, { ask('choose', {role='kp', seconds=60, yes='end', no='end', timeout='end'}) })"),"data",J.Obj("test.json",J.Obj("value",1)))));var artifact=await one.Request("admin/artifacts/"+staged);Assert(J.D(J.Get(artifact,"sourceChanges")).Count>0,"规则源码比较");Assert(J.S(J.Get(one.View,"catalog"),"rulesetRevision")==old,"暂存不自动激活");await Command(one,"rule.activate",J.Obj("revision",staged));
   var flow=await Command(one,"action.invoke",J.Obj("actionId","test.wait","input",J.Obj()));var wait=J.D(J.Get(one.View,"waits")).First();await Command(one,"flow.respond",J.Obj("waitId",wait.Key,"revision",J.Get(wait.Value,"revision"),"answer",false));await Command(one,"flow.respond",J.Obj("waitId",wait.Key,"revision",J.Get(wait.Value,"revision"),"answer",true),false);var flow2=await Command(one,"action.invoke",J.Obj("actionId","test.wait","input",J.Obj()));await Command(one,"flow.cancel",J.Obj("flowId",J.Get(flow2,"flowId")));await Command(one,"flow.retry",J.Obj("flowId",J.Get(flow2,"flowId")),false);var failedFlow=await Command(one,"action.invoke",J.Obj("actionId","test.retry","input",J.Obj()));await Command(one,"flow.retry",J.Obj("flowId",J.Get(failedFlow,"flowId")));await Command(one,"rule.activate",J.Obj("revision",old));
   await Command(one,"room.status",J.Obj("status","paused"));await Command(one,"room.status",J.Obj("status","active"));await Command(one,"entity.archive",J.Obj("id",id),true,Tokens(one,id));Assert(!J.D(J.Get(one.View,"entities")).ContainsKey(id),"归档对象退出活动投影");Assert(J.S(await one.Request("backup","POST",J.Obj()),"backupId")!="","宿主创建备份");
   await Command(one,"member.update",J.Obj("accountId","player2","role","kp"));using(var elevated=new ApiClient(endpoint)){await elevated.Login("player2",password);await Ready(elevated);await Command(one,"member.update",J.Obj("accountId","player2","role","player"));for(int i=0;i<40&&elevated.Connected;i++)await Task.Delay(100);Assert(!elevated.Connected&&elevated.View==null,"降权关闭流并清理视图");}await two.Logout();Assert(J.S(await one.Request("view"),"role")=="kp","关闭第二工具不影响宿主");
  }
 }
 static int Main(string[] args){endpoint=args[0];password=args[1];output=args[2];try{Run().GetAwaiter().GetResult();File.WriteAllText(Path.Combine(output,"integration.json"),J.Pretty(J.Obj("passed",checks,"failed",0,"at",DateTimeOffset.Now.ToString("o"))));return 0;}catch(Exception e){Console.WriteLine(e);File.WriteAllText(Path.Combine(output,"integration.json"),J.Pretty(J.Obj("passed",checks,"failed",1,"error",e.ToString())));return 1;}}
}
